// Supplied Task C checks. Students do not edit this file.
// This file compiles after you write Quiz in grade_item.h.
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include "../grade_item.h"

double totalPoints(const GradeItem* items[], int count);
int totalPossible(const GradeItem* items[], int count);
char letterGrade(double percent);
void printReport(const std::string& title, const GradeItem* items[], int count);

bool report(const char* name, bool ok)
{
    std::cout << (ok ? "PASS " : "FAIL ") << name << std::endl;
    return ok;
}

bool same(double a, double b)
{
    return std::fabs(a - b) < 1e-9;
}

std::string printedItem(const GradeItem& item)
{
    std::ostringstream text;
    std::streambuf* old = std::cout.rdbuf(text.rdbuf());
    item.print();
    std::cout.rdbuf(old);
    return text.str();
}

std::string printedReport(const std::string& title, const GradeItem* items[], int count)
{
    std::ostringstream text;
    std::streambuf* old = std::cout.rdbuf(text.rdbuf());
    printReport(title, items, count);
    std::cout.rdbuf(old);
    return text.str();
}

bool checkText(const std::string& expected, const std::string& actual)
{
    if (expected == actual)
        return true;
    std::cout << "  expected:\n" << expected;
    std::cout << "  printed:\n" << actual;
    return false;
}

int main()
{
    bool all = true;

    Quiz retakeHigher("Quiz 1", 6, 8, 10);
    Quiz firstHigher("Quiz 2", 9, 7, 10);
    Quiz retakeTooHigh("Quiz 3", 5, 12, 10);
    Quiz retakeNegative("Quiz 4", 5, -3, 10);
    Quiz firstTooHigh("Quiz 5", 14, 2, 10);
    if (!report("C01 Quiz keeps the better try",
        same(retakeHigher.finalPoints(), 8) && same(firstHigher.finalPoints(), 9) &&
        same(retakeTooHigh.finalPoints(), 10) && same(retakeNegative.finalPoints(), 5) &&
        same(firstTooHigh.finalPoints(), 10))) all = false;

    bool quizLines = checkText("Quiz 1: 8.0 / 10 (best of 6.0 and 8.0)\n",
                               printedItem(retakeHigher));
    quizLines = checkText("Quiz 3: 10.0 / 10 (best of 5.0 and 10.0)\n",
                          printedItem(retakeTooHigh)) && quizLines;
    if (!report("C02 Quiz print", quizLines)) all = false;

    if (!report("C03 letterGrade boundaries",
        letterGrade(100) == 'A' && letterGrade(90) == 'A' && letterGrade(89.9) == 'B' &&
        letterGrade(80) == 'B' && letterGrade(79.9) == 'C' && letterGrade(70) == 'C' &&
        letterGrade(69.9) == 'D' && letterGrade(60) == 'D' && letterGrade(59.9) == 'F' &&
        letterGrade(0) == 'F' && letterGrade(-1) == '?')) all = false;

    GradeItem homework("Homework 1", 9, 10);
    Lab lab("Lab 2", 18, 20, 2);
    Exam exam("Midterm", 78, 100, 5);
    const GradeItem* mixed[] = {&homework, &lab, &exam, &retakeHigher};
    if (!report("C04 totalPoints and totalPossible",
        same(totalPoints(mixed, 4), 114.4) && totalPossible(mixed, 4) == 140 &&
        same(totalPoints(mixed, 1), 9) && totalPossible(mixed, 1) == 10 &&
        same(totalPoints(nullptr, 4), 0) && totalPossible(nullptr, 4) == 0 &&
        same(totalPoints(mixed, 0), 0) && totalPossible(mixed, 0) == 0 &&
        same(totalPoints(mixed, -1), 0) && totalPossible(mixed, -1) == 0)) all = false;

    const GradeItem* small[] = {&homework, &lab};
    bool reports = checkText("Sample\n"
                             "Homework 1: 9.0 / 10\n"
                             "Lab 2: 14.4 / 20 (2 days late)\n"
                             "Total: 23.4 / 30\n"
                             "Percent: 78.0\n"
                             "Letter: C\n",
                             printedReport("Sample", small, 2));
    reports = checkText("Empty\nNo grade items\n",
                        printedReport("Empty", nullptr, 3)) && reports;
    reports = checkText("Empty\nNo grade items\n",
                        printedReport("Empty", small, 0)) && reports;
    if (!report("C05 printReport", reports)) all = false;

    return all ? 0 : 1;
}
